 import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec3,
  color,
  mix,
  smoothstep,
  add,
  sub,
  mul,
  div,
  fract,
  sin,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

const sanitizeForAtlas = (str = '') =>
  str
    .replace(/—/g, '--')
    .replace(/–/g, '-')
    .replace(/·/g, ' | ');

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SRGBColorSpace } = ctx.THREE;

  const root = new Group();
  root.userData.handlers = {};

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const palette = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const vUv = uv();
  const gradient = mix(
    color(palette.surface),
    color(palette.ink),
    smoothstep(0.25, 0.75, vUv.y)
  );

  const grain = sub(
    mul(
      fract(
        mul(
          sin(add(mul(vUv.x, 12.9898), mul(vUv.y, 78.233))),
          43758.5453
        )
      ),
      0.03
    ),
    0.015
  );

  const surfaceColor = add(gradient, vec3(grain));

  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });
  mat.colorNode = surfaceColor;

  const plane = new Mesh(new PlaneGeometry(1, 1), mat);
  plane.name = 'hero-subhead-surface';
  root.add(plane);

  let textObj;

  for (const item of items) {
    if (item.role === 'headline' || typeof item.text === 'string') {
      const copy = sanitizeForAtlas(item.text);
      textObj = ctx.fontAtlas.createText(copy, {
        fontSize: item.typography?.fontSize ? item.typography.fontSize / 210 : 0.2,
        color: palette.paper,
        align: 'center',
      });
      textObj.position.z = 0.04;
      textObj.name = 'hero-subhead-text';
      root.add(textObj);
      break;
    }
  }

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = SRGBColorSpace;
        tex.needsUpdate = true;

        const map = texture(tex, vUv);
        const blended = mix(surfaceColor, map.rgb, map.a);
        mat.colorNode = blended;
        mat.needsUpdate = true;

        const imgW = tex.image?.width || 512;
        const imgH = tex.image?.height || 320;
        const aspect = imgW / imgH || 1.6;
        const targetH = 0.55;
        plane.scale.set(targetH * aspect, targetH, 1);
      })
      .catch(() => {});
  }

  const tl = gsap.timeline();
  root.scale.set(1.04, 1.04, 1.04);

  tl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  if (textObj) {
    const startY = textObj.position.y + 0.08;
    textObj.position.y = startY;
    tl.to(
      textObj.position,
      {
        y: startY - 0.08,
        duration: 0.7,
        ease: 'power3.out',
      },
      0
    );
  }

  root.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(root.scale);
    if (textObj) gsap.killTweensOf(textObj.position);

    plane.geometry.dispose();
    if (plane.material) {
      if (plane.material.map) plane.material.map.dispose();
      plane.material.dispose();
    }
  };

  return root;
}
